-- Continues workflow.sql in the same disposable connection. Prices are fictional.
grant select,insert on ids to menu_platform;
insert into menumini.app_users(id,phone_e164,display_name) values(pg_temp.id(14),'+251900000014','Fictional phone-only owner');
select pg_temp.ok((select email is null and phone_verified_at is null from menumini.app_users where id=pg_temp.id(14)),'phone-first identity accepts absent email without claiming phone verification');
select pg_temp.reject($q$insert into menumini.app_users(display_name) values('No contact')$q$,'23514','identity still requires a phone or email contact');
select pg_temp.reject($q$insert into menumini.app_users(display_name,phone_e164) values('Bad format','0900000015')$q$,'23514','identity phone storage requires canonical international format');
select pg_temp.reject($q$insert into menumini.app_users(display_name,phone_e164) values('Duplicate phone','+251900000014')$q$,'23505','same phone cannot create independent duplicate identities');
begin; set local role menu_runtime; select pg_temp.ctx(3,13);
insert into ids values('mini-first',menumini.create_branch('Fictional C First','fictional-c-first',pg_temp.id(931)));
insert into ids values('mini-request',menumini.request_mini_branch(pg_temp.id(932)));
select pg_temp.ok(menumini.request_mini_branch(pg_temp.id(932))=(select id from ids where name='mini-request'),'second Mini branch request retries return the same request');
select pg_temp.ok((select branch_limit=1 from menumini.merchants where id=pg_temp.id(3)),'requesting the price increase does not activate branch capacity');
select pg_temp.reject($q$select menumini.create_branch('C Second','c-second-before-price',pg_temp.id(933))$q$,'23514','second Mini branch stays blocked before pricing acceptance and billing activation');
commit;
begin; set local role menu_platform; select pg_temp.ctx(3,99);
select pg_temp.reject($q$select menumini.apply_plan(pg_temp.id(3),'MINI',2,true,now(),now()+interval '1 month','FICTIONAL-BYPASS')$q$,'23514','platform generic activation cannot bypass owner price consent for branch two');
select pg_temp.reject($q$select menumini.apply_plan(pg_temp.id(3),'MINI',3,true,now(),now()+interval '1 month','FICTIONAL-THREE')$q$,'23514','MenuMini hard ceiling is two even for platform billing');
commit;
begin; set local role menu_runtime; select pg_temp.ctx(3,13);
select pg_temp.reject($q$select menumini.quote_mini_branch((select id from ids where name='mini-request'),600,900,150,'MONTH',now(),now()+interval '1 month',now()+interval '1 day',pg_temp.id(934))$q$,'42501','owner cannot invent a platform price quote');
commit;
begin; set local role menu_platform; select pg_temp.ctx(3,99);
insert into ids values('mini-quote',menumini.quote_mini_branch((select id from ids where name='mini-request'),600,900,150,'MONTH',now(),now()+interval '1 month',now()+interval '1 day',pg_temp.id(934)));
select pg_temp.ok(menumini.quote_mini_branch((select id from ids where name='mini-request'),600,900,150,'MONTH',now(),now()+interval '1 month',now()+interval '1 day',pg_temp.id(934))=(select id from ids where name='mini-quote'),'exact quote retry returns the same immutable offer');
select pg_temp.reject($q$select menumini.quote_mini_branch((select id from ids where name='mini-request'),600,950,150,'MONTH',now(),now()+interval '1 month',now()+interval '1 day',pg_temp.id(934))$q$,'40001','same quote request key cannot change price');
select pg_temp.reject($q$select menumini.activate_mini_branch_quote((select id from ids where name='mini-quote'),'FICTIONAL-SAAS-ADDON',pg_temp.id(936))$q$,'23514','billing cannot activate an unaccepted quote');
commit;
begin; set local role menu_runtime; select pg_temp.ctx(1,11);
select pg_temp.ok((select count(*)=0 from menumini.mini_branch_quotes),'other business cannot read private Mini branch pricing');
select pg_temp.reject($q$select menumini.accept_mini_branch_quote((select id from ids where name='mini-quote'),pg_temp.id(935))$q$,'42501','other business owner cannot accept a quote');
select pg_temp.ctx(3,13);
select menumini.accept_mini_branch_quote((select id from ids where name='mini-quote'),pg_temp.id(935));
select pg_temp.ok(menumini.accept_mini_branch_quote((select id from ids where name='mini-quote'),pg_temp.id(935))=(select id from ids where name='mini-quote'),'owner quote acceptance is safely repeatable');
select pg_temp.ok((select branch_limit=1 from menumini.merchants where id=pg_temp.id(3)),'accepting a price does not assert that subscription funds were received');
select pg_temp.reject($q$select menumini.activate_mini_branch_quote((select id from ids where name='mini-quote'),'FICTIONAL-SAAS-ADDON',pg_temp.id(936))$q$,'42501','restaurant owner cannot self-activate paid branch access');
commit;
begin; set local role menu_platform; select pg_temp.ctx(3,99);
insert into ids values('mini-addon-term',menumini.activate_mini_branch_quote((select id from ids where name='mini-quote'),'FICTIONAL-SAAS-ADDON',pg_temp.id(936)));
select pg_temp.ok(menumini.activate_mini_branch_quote((select id from ids where name='mini-quote'),'FICTIONAL-SAAS-ADDON',pg_temp.id(936))=(select id from ids where name='mini-addon-term'),'activation retry cannot apply the same quote twice');
select pg_temp.reject($q$select menumini.activate_mini_branch_quote((select id from ids where name='mini-quote'),'DIFFERENT-EVIDENCE',pg_temp.id(936))$q$,'40001','activation retry cannot replace verified billing evidence');
commit;
begin; set local role menu_runtime; select pg_temp.ctx(3,13);
select pg_temp.ok((select plan='MINI' and branch_limit=2 from menumini.merchants where id=pg_temp.id(3)),'second-branch entitlement keeps the business on MenuMini');
select pg_temp.ok((select current_recurring_amount=600 and new_recurring_amount=900 and amount_due_now=150 from menumini.mini_branch_quotes),'quote retains period pricing and immediate amount separately');
select pg_temp.reject($q$update menumini.mini_branch_quotes set new_recurring_amount=1000$q$,'42501','runtime cannot change accepted quote prices');
commit;
select pg_temp.ok((select count(*)=4 from menumini.audit_events where merchant_id=pg_temp.id(3) and action like 'MINI_SECOND_BRANCH_%'),'request, quote, owner acceptance and activation each have durable audit history');
select pg_temp.reject($q$update menumini.mini_branch_quotes set new_recurring_amount=1000 where id=(select id from ids where name='mini-quote')$q$,'23514','database trigger prevents rewriting a committed price offer');
begin; set local role menu_runtime; select pg_temp.ctx(1,21);
select pg_temp.reject($q$select menumini.request_mini_branch(pg_temp.id(937))$q$,'42501','ordinary staff cannot request software subscription changes');
select pg_temp.ctx(1,11);
insert into ids values('expired-mini-request',menumini.request_mini_branch(pg_temp.id(937)));
commit;
begin; set local role menu_platform; select pg_temp.ctx(1,99);
insert into ids values('expired-mini-quote',menumini.quote_mini_branch((select id from ids where name='expired-mini-request'),600,900,150,'MONTH',now(),now()+interval '1 month',now()+interval '0.1 second',pg_temp.id(938)));
commit;
select pg_sleep(0.2);
begin; set local role menu_runtime; select pg_temp.ctx(1,11);
select pg_temp.reject($q$select menumini.accept_mini_branch_quote((select id from ids where name='expired-mini-quote'),pg_temp.id(939))$q$,'40001','expired price offer cannot obtain owner consent');
commit;
